<script setup>
import { inject, ref } from 'vue';
import { formatMoney } from '@/Utils/format';
defineProps({ trip: Object, history: Array, runs: Array });
const route = inject('route');
const expanded = ref(null);
const labels = { update: 'Actualización del lote', product_create: 'Producto agregado', product_update: 'Producto actualizado', product_delete: 'Producto eliminado', expense_create: 'Gasto agregado', expense_update: 'Gasto actualizado', expense_delete: 'Gasto eliminado', price_update: 'Precio de venta actualizado', document_upload: 'Documento adjunto', document_trash: 'Documento a papelera', document_restore: 'Documento restaurado', company_assignment: 'Empresa asignada', configuration: 'Configuración y revaluación', close: 'Cierre de importación', reopen: 'Reapertura de importación' };
const date = value => new Date(value).toLocaleString('es-CL');
</script>
<template>
    <section class="f-panel"><div class="f-panel-heading"><h2>Revisiones conservadas</h2><span class="f-hint">Últimas 50 ejecuciones</span></div><div class="f-panel-body"><div v-for="run in runs" :key="run.id" class="f-breakdown-row" style="flex-wrap:wrap;align-items:center"><div><strong>Revisión {{ run.revision }} · {{ labels[run.reason] || run.reason }}</strong><p class="f-hint">{{ date(run.created_at) }} · {{ run.algorithm }}</p></div><div class="f-actions"><a :href="`${route('trips.export.pdf', trip.id)}?run=${run.id}`" class="f-button">PDF de esta revisión</a><a :href="`${route('trips.export.excel', trip.id)}?run=${run.id}`" class="f-button">Excel de esta revisión</a></div></div><p v-if="!runs.length" class="f-hint">Aún no hay una ejecución registrada. Los datos heredados se conservan con su procedencia sin verificar.</p></div></section>
    <section class="f-panel"><div class="f-panel-heading"><h2>Registro de cambios</h2><span class="f-hint">Actor, estado anterior y resultado</span></div><div class="f-panel-body"><article v-for="event in history" :key="event.id" style="border-bottom:1px solid var(--f-line);padding:12px 0"><button class="f-breakdown-row" style="width:100%;text-align:left;border:0;padding:0" :aria-expanded="expanded === event.id" @click="expanded = expanded === event.id ? null : event.id"><span><strong>{{ labels[event.action] || event.action }}</strong><span class="f-table-subtitle">{{ event.actor?.name || 'Proceso del sistema' }} · {{ date(event.created_at) }}</span></span><span class="f-hint">Revisión {{ event.revision }} {{ expanded === event.id ? '−' : '+' }}</span></button><div v-if="expanded === event.id" class="f-draft" style="margin-top:12px"><div class="f-breakdown-row"><span>Estado</span><strong>{{ event.before.estado }} → {{ event.after.estado }}</strong></div><div class="f-breakdown-row"><span>Tasa de referencia</span><strong>{{ event.before.tipo_cambio }} → {{ event.after.tipo_cambio }}</strong></div><div class="f-breakdown-row"><span>Productos</span><strong>{{ event.before.products?.length || 0 }} → {{ event.after.products?.length || 0 }}</strong></div><div class="f-breakdown-row"><span>Gastos</span><strong>{{ event.before.expenses?.length || 0 }} → {{ event.after.expenses?.length || 0 }}</strong></div><div class="f-breakdown-row"><span>Costo del lote · CLP</span><strong>${{ formatMoney(event.before.costo_total) }} → ${{ formatMoney(event.after.costo_total) }}</strong></div></div></article><p v-if="!history.length" class="f-hint">Los nuevos cambios se registrarán aquí con su autor.</p></div></section>
</template>
